solution.solution.py:
def to_cents(text):
    parts = text.split(".")
    whole = int(parts[0]) if parts[0] else 0
    cents = 0
    if len(parts) == 2:
        fraction = (parts[1] + "00")[:2]
        cents = int(fraction)
    return whole * 100 + cents

def show(cents):
    return f"{cents // 100}.{cents % 100:02d}"

def close_enough(a, b):
    return abs(a - b) < 1e-9

unitTests:
@test("reading amounts")
def _():
    check_eq(to_cents("12.34"), 1234)
    check_eq(to_cents("5"), 500)
    check_eq(to_cents("0.5"), 50)
    check_eq(to_cents("7.05"), 705)
    check_eq(to_cents("0.10"), 10)

@test("showing amounts")
def _():
    check_eq(show(1234), "12.34")
    check_eq(show(5), "0.05")
    check_eq(show(100), "1.00")
    check_eq(show(0), "0.00")

@test("ten cents a hundred times is exactly ten")
def _():
    total = 0
    for _ in range(100):
        total += to_cents("0.10")
    check_eq(show(total), "10.00")

@test("comparing floats safely")
def _():
    check(close_enough(0.1 + 0.2, 0.3))
    check(not close_enough(0.1, 0.11))

